import heapq

def match(orders):
    trades = []
    # order books: for buy side, max-heap by price then min by time -> use (-price, time)
    buy_heap = []
    sell_heap = []
    # store order info by id: [side, price, qty_remaining, time, active]
    book = {}
    time_counter = 0

    def add_to_book(oid, side, price, qty, t):
        book[oid] = [side, price, qty, t, True]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, t, oid))
        else:
            heapq.heappush(sell_heap, (price, t, oid))

    def clean_buy_heap():
        while buy_heap:
            negp, t, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            p, t, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info[4] and info[2] > 0:
                info[4] = False
            continue

        oid = order[1]
        side = order[2]
        t = time_counter
        time_counter += 1

        if typ == 'limit':
            price = order[3]
            qty = order[4]
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
        elif typ == 'market':
            price = None
            qty = order[3]

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                p, st, sid = sell_heap[0]
                if typ != 'market' and p > price:
                    break
                sinfo = book[sid]
                trade_qty = min(remaining, sinfo[2])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                sinfo[2] -= trade_qty
                if sinfo[2] <= 0:
                    heapq.heappop(sell_heap)
                    sinfo[4] = False
            if typ == 'limit' and remaining > 0:
                add_to_book(oid, side, price, remaining, t)
            else:
                if oid not in book:
                    book[oid] = [side, price if price is not None else 0, 0, t, False]
        else:
            # sell side, match against buy_heap
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negp, bt, bid = buy_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                binfo = book[bid]
                trade_qty = min(remaining, binfo[2])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                binfo[2] -= trade_qty
                if binfo[2] <= 0:
                    heapq.heappop(buy_heap)
                    binfo[4] = False
            if typ == 'limit' and remaining > 0:
                add_to_book(oid, side, price, remaining, t)
            else:
                if oid not in book:
                    book[oid] = [side, price if price is not None else 0, 0, t, False]

    return trades

